"use client";

import { useEffect } from "react";

export default function PrivacyPolicy() {
  useEffect(() => {
    window.location.href = "/tcp.pdf";  // Adjust path if needed (place PDF in public/)
  }, []);

  return (
    <div className="min-h-screen bg-white py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto text-center">
        <h1 className="text-4xl font-bold mb-8">Privacy Policy</h1>
        <p className="text-gray-600 mb-8">
          Redirecting to the PDF document... If it doesn't open automatically,{' '}
          <a href="/Teraawatt_Compliance_Policy.pdf" className="text-green-600 hover:underline">
            click here to open it
          </a>.
        </p>
        <div className="mt-12">
          <a href="/" className="text-green-600 hover:underline">
            ← Back to Home
          </a>
        </div>
      </div>
    </div>
  );
}